{"command":"python3 -c "
import re

with open('reports/pipeline_report.md', 'r') as f:
    content = f.read()

sections = ['Overview', 'Input data', 'Methods', 'Generated outputs', 'Main results', 'Limitations', 'Reproducibility']
for section in sections:
    pattern = rf'^#{section}\s*\n(.+?)(?=\n# |\Z)'
    match = re.search(pattern, content, re.MULTILINE | re.DOTALL)
    if match:
        text = match.group(1)
        print(f'{section}: {len(text)} chars')
        if len(text) < 80:
            print(f'  WARNING: Less than 80 characters!')
        else:
            print(f'  OK')
    else:
        print(f'{section}: NOT FOUND')
""}

