with open('reports/pipeline_report.md', 'r') as f:
    lines = f.readlines()

# Find sections and their content
sections = {}
current_section = None
for line in lines:
    if line.startswith('# '):
        section_name = line[2:].strip()
        if current_section and section_name in sections:
            sections[section_name] = lines[current_section]
        current_section = line
        sections[section_name] = []

    if current_section is not None:
        sections[current_section].append(line)

for section_name, content in sections.items():
    text = ''.join(content).strip()
    print(f'{section_name}: {len(text)} chars')
    if len(text) < 80:
        print(f'  WARNING: Less than 80 characters!')
    else:
        print(f'  OK')
""}

